const fs = require("fs")
const path = require("path")

function read(file) {
  return fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n")
}

function decode(value) {
  return Buffer.from(value, "base64").toString("utf8")
}

function countOf(content, needle) {
  if (!needle) return 0
  return content.split(needle).length - 1
}

function replaceExact(content, oldText, newText, label, expected = 1) {
  const count = countOf(content, oldText)
  if (count !== expected) {
    throw new Error(
      `${label}: esperado ${expected} trecho(s), encontrado(s) ${count}. Nenhum arquivo foi alterado.`
    )
  }

  if (expected === 1) {
    return content.replace(oldText, newText)
  }

  return content.split(oldText).join(newText)
}

function ensureParent(file) {
  fs.mkdirSync(path.dirname(file), { recursive: true })
}

